export const envelope = [25, 42, 25];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 12;
  const cz = 12;
  const seatY = 3; // Buffer plane allowing foundation roots to sink into terrain dips

  // Theme-aware palette bindings
  const woodPlanks = api.theme.wood.planks || "minecraft:oak_planks";
  const woodFence = api.theme.wood.fence || "minecraft:oak_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:oak_trapdoor";
  const groundPavement = api.theme.ground.pavement || "minecraft:mossy_cobblestone";
  const stoneWall = api.theme.stone.wall || "minecraft:cobblestone_wall";

  // Specialized fungal blocks
  const stemBlock = "minecraft:mushroom_stem";
  const redCapBlock = "minecraft:red_mushroom_block";
  const brownCapBlock = "minecraft:brown_mushroom_block";
  const glowBlock = "minecraft:shroomlight";
  const froglightBlock = "minecraft:ochre_froglight";
  const chainBlock = "minecraft:chain[axis=y]";
  const soulLantern = "minecraft:soul_lantern[hanging=true]";

  // Safe block placement helper
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Pre-generate deterministic spore spot centers on the cap
  const sporeSpots = [];
  const spotCount = 28;
  for (let i = 0; i < spotCount; i++) {
    const u = api.random();
    const v = api.random();
    const theta = u * 2 * Math.PI;
    const phi = Math.acos(2 * v - 1) * 0.5; // Top hemisphere
    const r = 9.5;
    sporeSpots.push({
      x: cx + r * Math.sin(phi) * Math.cos(theta),
      y: seatY + 22 + r * Math.cos(phi) * 0.85,
      z: cz + r * Math.sin(phi) * Math.sin(theta),
      isGlow: api.random() < 0.45
    });
  }

  // Radii calculation functions for stalk and cap
  function stalkOuterRadius(yRel) {
    // yRel in [0, 22]
    const t = yRel / 22;
    // Flared base, pinched waist around yRel=10, flared under-cap collar
    return 5.8 - 2.0 * Math.sin(t * Math.PI) + 2.8 * Math.pow(t, 2.2);
  }

  function stalkInnerRadius(yRel) {
    const out = stalkOuterRadius(yRel);
    return Math.max(1.8, out - 1.7);
  }

  function capOuterRadius(yRel) {
    // yRel in [21, 34] (relative to seatY)
    const t = (yRel - 21) / 13;
    if (t < 0) return 0;
    if (t > 1) return 0;
    // Broad mushroom umbrella dome
    return 11.2 * Math.sqrt(Math.max(0, 1 - Math.pow(t, 1.35))) * (1 - 0.12 * t);
  }

  // 1. FOUNDATIONS & ROOT BUTTRESSES (Conforming to terrain)
  const rootAngles = [0, 1.05, 2.09, 3.14, 4.19, 5.24];
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.hypot(dx, dz);
      const angle = Math.atan2(dz, dx);

      // Root buttress modulation
      let maxRootMod = 0;
      for (const ra of rootAngles) {
        const diff = Math.abs(Math.atan2(Math.sin(angle - ra), Math.cos(angle - ra)));
        const mod = Math.max(0, Math.cos(diff * 2.5));
        if (mod > maxRootMod) maxRootMod = mod;
      }
      const rootReach = 5.5 + maxRootMod * 3.4;

      if (dist <= rootReach) {
        const groundH = api.heightAt(x, z);
        const startY = Math.max(0, Math.min(seatY, seatY + groundH));
        for (let y = startY; y <= seatY + 2; y++) {
          const rBase = rootReach * (1 - (y - startY) / 5.5);
          if (dist <= rBase) {
            setBlock(x, y, z, dist > rBase - 1.2 ? groundPavement : stemBlock);
          }
        }
      }
    }
  }

  // 2. MAIN HOLLOW STALK & FLOORS
  for (let y = seatY; y <= seatY + 22; y++) {
    const yRel = y - seatY;
    const rOut = stalkOuterRadius(yRel);
    const rIn = stalkInnerRadius(yRel);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dist = Math.hypot(x - cx, z - cz);
        const angle = Math.atan2(z - cz, x - cx);

        // Subtle biological ribbing
        const rib = 0.25 * Math.sin(angle * 8 + yRel * 0.35);
        const effectiveDist = dist + rib;

        if (effectiveDist <= rOut && effectiveDist >= rIn) {
          // Stalk wall with organic fungal grain
          if ((x + y + z) % 7 === 0) {
            setBlock(x, y, z, brownCapBlock);
          } else {
            setBlock(x, y, z, stemBlock);
          }
        } else if (y === seatY && dist < rIn) {
          // Ground floor inside stalk
          setBlock(x, y, z, groundPavement);
        }
      }
    }
  }

  // 3. SPIRAL SHELF-FUNGUS STAIRWAY (Interior ascent)
  for (let y = seatY + 1; y <= seatY + 21; y++) {
    const yRel = y - seatY;
    const theta = yRel * 0.62; // Smooth winding angle
    const rIn = stalkInnerRadius(yRel);

    // Build stepping shelf voxels hugging the inner wall
    for (let offset = -0.3; offset <= 0.3; offset += 0.25) {
      const curTheta = theta + offset;
      const sr = rIn - 0.6;
      const sx = Math.round(cx + Math.cos(curTheta) * sr);
      const sz = Math.round(cz + Math.sin(curTheta) * sr);

      setBlock(sx, y, sz, brownCapBlock);
      // Fungal bracket support underneath
      setBlock(sx, y - 1, sz, stemBlock);

      // Inner walkable surface
      const inX = Math.round(cx + Math.cos(curTheta) * (sr - 0.7));
      const inZ = Math.round(cz + Math.sin(curTheta) * (sr - 0.7));
      setBlock(inX, y, inZ, woodPlanks);
    }
  }

  // 4. EXTERIOR BALCONY SHELF FUNGI
  const balconies = [
    { yRel: 6, angle: 0.8, reach: 3.0 },
    { yRel: 12, angle: 3.3, reach: 3.2 },
    { yRel: 17, angle: 5.4, reach: 2.8 }
  ];

  for (const b of balconies) {
    const by = seatY + b.yRel;
    const rOut = stalkOuterRadius(b.yRel);
    const centerDist = rOut + b.reach * 0.5;
    const bx = cx + Math.cos(b.angle) * centerDist;
    const bz = cz + Math.sin(b.angle) * centerDist;

    // Shelf disc
    for (let x = Math.floor(bx - 3); x <= Math.ceil(bx + 3); x++) {
      for (let z = Math.floor(bz - 3); z <= Math.ceil(bz + 3); z++) {
        const dShelf = Math.hypot(x - bx, z - bz);
        if (dShelf <= b.reach * 0.7) {
          setBlock(x, by, z, brownCapBlock);
          setBlock(x, by - 1, z, stemBlock);

          // Edge railing
          if (dShelf > b.reach * 0.7 - 0.9 && (x !== Math.round(bx) || z !== Math.round(bz))) {
            setBlock(x, by + 1, z, woodFence);
          }
        }
      }
    }

    // Balcony lantern
    const lanternX = Math.round(cx + Math.cos(b.angle) * (rOut + b.reach * 0.8));
    const lanternZ = Math.round(cz + Math.sin(b.angle) * (rOut + b.reach * 0.8));
    setBlock(lanternX, by + 1, lanternZ, woodFence);
    setBlock(lanternX, by + 2, lanternZ, froglightBlock);

    // Balcony doorway through stalk wall
    for (let dy = 1; dy <= 3; dy++) {
      for (let step = 0; step <= 3; step++) {
        const dPass = rOut - 1.8 + step * 0.8;
        const passX = Math.round(cx + Math.cos(b.angle) * dPass);
        const passZ = Math.round(cz + Math.sin(b.angle) * dPass);
        setBlock(passX, by + dy, passZ, "minecraft:air");
      }
    }
  }

  // 5. ENTRANCE ARCHWAY (Facing Local North: -Z)
  for (let z = cz - 7; z <= cz - 3; z++) {
    for (let x = cx - 2; x <= cx + 2; x++) {
      for (let y = seatY + 1; y <= seatY + 4; y++) {
        const dx = x - cx;
        const dy = y - (seatY + 1);
        if ((dx * dx) / 4 + (dy * dy) / 9 <= 1) {
          setBlock(x, y, z, "minecraft:air");
        }
      }
    }
  }
  // Archway frame & threshold lanterns
  setBlock(cx - 2, seatY + 1, cz - 6, woodFence);
  setBlock(cx - 2, seatY + 2, cz - 6, glowBlock);
  setBlock(cx + 2, seatY + 1, cz - 6, woodFence);
  setBlock(cx + 2, seatY + 2, cz - 6, glowBlock);

  // 6. CENTRAL HANGING SPORE BRAZIERS (Spine of light in hollow core)
  for (let y = seatY + 4; y <= seatY + 22; y++) {
    // Central suspended chain
    setBlock(cx, y, cz, chainBlock);

    // Glowing node clusters at harmonic heights
    if (y === seatY + 6 || y === seatY + 12 || y === seatY + 18) {
      setBlock(cx, y, cz, glowBlock);
      setBlock(cx + 1, y, cz, woodTrapdoor);
      setBlock(cx - 1, y, cz, woodTrapdoor);
      setBlock(cx, y, cz + 1, woodTrapdoor);
      setBlock(cx, y, cz - 1, woodTrapdoor);
      setBlock(cx, y - 1, cz, chainBlock);
      setBlock(cx, y - 2, cz, soulLantern);
    }
  }

  // 7. UNDER-CAP GILLS (Bioluminescent radial vanes)
  for (let y = seatY + 20; y <= seatY + 23; y++) {
    const yRel = y - seatY;
    const rOut = stalkOuterRadius(yRel) + (yRel - 20) * 1.8;
    const rIn = stalkInnerRadius(yRel);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dist = Math.hypot(x - cx, z - cz);
        if (dist >= rIn && dist <= rOut) {
          const angle = Math.atan2(z - cz, x - cx);
          const gillWave = Math.sin(angle * 16);

          if (Math.abs(gillWave) > 0.45) {
            setBlock(x, y, z, stemBlock);
          } else if (y >= seatY + 22) {
            setBlock(x, y, z, glowBlock);
          }
        }
      }
    }
  }

  // 8. UPPER SPORE SANCTUM (Chamber floor & Sacred Altar)
  const sanctumY = seatY + 22;
  for (let x = cx - 5; x <= cx + 5; x++) {
    for (let z = cz - 5; z <= cz + 5; z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist <= 5.0) {
        // Floor inlay
        if (dist <= 1.8) {
          setBlock(x, sanctumY, z, froglightBlock);
        } else if (dist <= 3.6) {
          setBlock(x, sanctumY, z, woodPlanks);
        } else {
          setBlock(x, sanctumY, z, brownCapBlock);
        }
      }
    }
  }

  // Central Altar of the Mother Spore
  setBlock(cx, sanctumY + 1, cz, stoneWall);
  setBlock(cx, sanctumY + 2, cz, glowBlock);
  setBlock(cx + 1, sanctumY + 1, cz, woodFence);
  setBlock(cx - 1, sanctumY + 1, cz, woodFence);
  setBlock(cx, sanctumY + 1, cz + 1, woodFence);
  setBlock(cx, sanctumY + 1, cz - 1, woodFence);

  // Sanctum gill windows at 4 cardinal directions
  for (let dy = 1; dy <= 3; dy++) {
    setBlock(cx, sanctumY + dy, cz - 6, "minecraft:air");
    setBlock(cx, sanctumY + dy, cz + 6, "minecraft:air");
    setBlock(cx - 6, sanctumY + dy, cz, "minecraft:air");
    setBlock(cx + 6, sanctumY + dy, cz, "minecraft:air");
  }

  // 9. THE COLOSSAL ELDER MUSHROOM CAP
  for (let y = seatY + 21; y <= seatY + 34; y++) {
    const yRel = y - seatY;
    const rCapOut = capOuterRadius(yRel);
    if (rCapOut <= 0.2) continue;

    // Hollow sanctum dome inside the cap up to yRel = 29
    const rCapIn = yRel <= 29 ? Math.max(0, rCapOut - 1.8) : 0;

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dist = Math.hypot(x - cx, z - cz);
        if (dist <= rCapOut && dist >= rCapIn) {
          // Check proximity to spore spots for glowing nodes & mycelium flecks
          let isSpot = false;
          let isGlowSpot = false;
          for (const s of sporeSpots) {
            const sd = Math.hypot(x - s.x, y - s.y, z - s.z);
            if (sd < 1.6) {
              isSpot = true;
              if (s.isGlow) isGlowSpot = true;
              break;
            }
          }

          if (isGlowSpot) {
            setBlock(x, y, z, glowBlock);
          } else if (isSpot) {
            setBlock(x, y, z, stemBlock);
          } else {
            // Main Elder Red Cap body
            setBlock(x, y, z, redCapBlock);
          }
        } else if (dist < rCapIn && y > sanctumY) {
          // Clear air inside the upper sanctuary
          setBlock(x, y, z, "minecraft:air");
        }
      }
    }
  }

  // 10. BIOLUMINESCENT DRIPPING SPORE TENDRILS (Hanging from cap perimeter)
  for (let i = 0; i < 16; i++) {
    const angle = (i / 16) * 2 * Math.PI + 0.1;
    const rimY = seatY + 22;
    const rimR = capOuterRadius(22) - 0.4;
    const hx = Math.round(cx + Math.cos(angle) * rimR);
    const hz = Math.round(cz + Math.sin(angle) * rimR);

    const tendrilLength = 2 + Math.floor(api.random() * 4);
    for (let ty = 1; ty <= tendrilLength; ty++) {
      const dropY = rimY - ty;
      if (ty === tendrilLength) {
        setBlock(hx, dropY, hz, froglightBlock);
      } else {
        setBlock(hx, dropY, hz, chainBlock);
      }
    }
  }

  // Crown pinnacle spore
  setBlock(cx, seatY + 34, cz, stemBlock);
  setBlock(cx, seatY + 35, cz, glowBlock);

  return {
    name: "mother_spore_spire",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      door: [cx, seatY + 1, cz - 6],
      sanctum: [cx, sanctumY + 1, cz],
      crown: [cx, seatY + 35, cz]
    },
    interiors: [
      {
        min: [cx - 2, seatY + 1, cz - 2],
        max: [cx + 2, seatY + 7, cz + 2],
        kind: "hall"
      },
      {
        min: [cx - 3, sanctumY + 1, cz - 3],
        max: [cx + 3, sanctumY + 6, cz + 3],
        kind: "sanctuary"
      }
    ]
  };
}

