export const envelope = [11, 15, 11];

export default function build(api) {
  const rng = () => api.random();

  // Theme extractions with safe fungal/wood fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:oak_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:mushroom_stem";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_oak_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:oak_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:oak_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:oak_trapdoor";
  const woodDoor = api.theme?.wood?.door || "minecraft:oak_door";

  // Safe placement within envelope
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < 11 && y >= 0 && y < 15 && z >= 0 && z < 11) {
      api.set(x, y, z, block);
    }
  }

  // Follow terrain downward for footings and stilts
  function fillDown(x, z, startY, block) {
    const gh = api.heightAt(x, z);
    const minY = Math.min(0, Math.min(gh, startY));
    for (let y = minY; y <= startY; y++) {
      setBlock(x, y, z, block);
    }
  }

  // Instance variation parameters
  const platY = rng() < 0.5 ? 4 : 5;
  const capType = Math.floor(rng() * 3); // 0: Red Amanita, 1: Brown Shelf Bonnet, 2: Glowing Sporecap
  const stalkStyle = Math.floor(rng() * 3); // 0: Giant trunk + buttresses, 1: Splayed stilts, 2: Cluster stilts

  const stemBlock = (rng() < 0.5) ? "minecraft:mushroom_stem" : woodStripped;
  const primaryCap = capType === 1 ? "minecraft:brown_mushroom_block" : "minecraft:red_mushroom_block";
  const spotBlock = capType === 0 ? "minecraft:mushroom_stem" : (capType === 1 ? "minecraft:shroomlight" : "minecraft:ochre_froglight");

  // ==========================================
  // 1. ELEVATED STILTS & FOUNDATIONS
  // ==========================================
  if (stalkStyle === 0) {
    // Central massive stalk
    for (let dx = 0; dx <= 1; dx++) {
      for (let dz = 0; dz <= 1; dz++) {
        fillDown(4 + dx, 4 + dz, platY, stemBlock);
      }
    }
    // Corner support stilts
    const legCoords = [[3, 3], [7, 3], [3, 7], [7, 7]];
    for (const [lx, lz] of legCoords) {
      fillDown(lx, lz, platY - 1, woodLog);
      setBlock(lx, platY - 1, lz, woodFence);
    }
  } else if (stalkStyle === 1) {
    // Splayed 4-corner crooked stilts
    const stilts = [
      { bot: [2, 2], top: [3, 3] },
      { bot: [8, 2], top: [7, 3] },
      { bot: [2, 8], top: [3, 7] },
      { bot: [8, 8], top: [7, 7] }
    ];
    for (const s of stilts) {
      fillDown(s.bot[0], s.bot[1], 1, woodLog);
      for (let y = 2; y <= platY; y++) {
        setBlock(s.top[0], y, s.top[1], woodLog);
      }
    }
    // Center support stem
    fillDown(5, 5, platY, stemBlock);
  } else {
    // Cluster stalks with cross-bracing
    fillDown(5, 5, platY, stemBlock);
    fillDown(4, 5, platY - 1, woodLog);
    fillDown(6, 5, platY - 1, woodLog);
    fillDown(5, 4, platY - 1, woodLog);
    fillDown(5, 6, platY - 1, woodLog);

    const outerLegs = [[3, 3], [7, 3], [3, 7], [7, 7]];
    for (const [lx, lz] of outerLegs) {
      fillDown(lx, lz, platY - 2, woodFence);
      setBlock(lx, platY - 1, lz, woodStairs + "[facing=north,half=top]");
    }
  }

  // Cross brackets under the platform
  setBlock(5, platY - 1, 3, woodStairs + "[facing=south,half=top]");
  setBlock(5, platY - 1, 7, woodStairs + "[facing=north,half=top]");
  setBlock(3, platY - 1, 5, woodStairs + "[facing=east,half=top]");
  setBlock(7, platY - 1, 5, woodStairs + "[facing=west,half=top]");

  // ==========================================
  // 2. DWELLING PLATFORM (y = platY)
  // ==========================================
  for (let x = 2; x <= 8; x++) {
    for (let z = 2; z <= 8; z++) {
      const dx = x - 5;
      const dz = z - 5;
      const distSq = dx * dx + dz * dz;
      if (distSq <= 10) {
        const isRim = distSq >= 8;
        setBlock(x, platY, z, isRim ? woodStripped : woodPlanks);
      }
    }
  }

  // Entrance landing porch
  setBlock(5, platY, 2, woodPlanks);
  setBlock(4, platY, 2, woodPlanks);
  setBlock(6, platY, 2, woodPlanks);
  setBlock(4, platY + 1, 2, woodFence);
  setBlock(6, platY + 1, 2, woodFence);

  // Entrance ladder on solid post
  fillDown(5, 2, platY, woodLog);
  const ladderBottom = Math.max(0, api.heightAt(5, 1));
  for (let y = ladderBottom; y <= platY; y++) {
    setBlock(5, y, 1, "minecraft:ladder[facing=north]");
  }

  // ==========================================
  // 3. ORGANIC WALLS (y = platY + 1 .. platY + 3)
  // ==========================================
  for (let y = platY + 1; y <= platY + 3; y++) {
    // Corner posts
    setBlock(3, y, 3, woodLog);
    setBlock(7, y, 3, woodLog);
    setBlock(3, y, 7, woodLog);
    setBlock(7, y, 7, woodLog);

    // North wall
    setBlock(4, y, 3, woodPlanks);
    setBlock(6, y, 3, woodPlanks);

    // South wall
    setBlock(4, y, 7, woodPlanks);
    setBlock(6, y, 7, woodPlanks);
    setBlock(5, y, 7, (y === platY + 2) ? woodFence : woodPlanks);

    // West wall
    setBlock(3, y, 4, woodPlanks);
    setBlock(3, y, 6, woodPlanks);
    setBlock(3, y, 5, (y === platY + 2) ? woodFence : woodPlanks);

    // East wall
    setBlock(7, y, 4, woodPlanks);
    setBlock(7, y, 6, woodPlanks);
    setBlock(7, y, 5, (y === platY + 2) ? woodFence : woodPlanks);
  }

  // Doorway on north wall
  const doorBlock = woodDoor.includes("[") ? woodDoor.split("[")[0] : woodDoor;
  setBlock(5, platY + 1, 3, `${doorBlock}[facing=north,half=lower,hinge=left]`);
  setBlock(5, platY + 2, 3, `${doorBlock}[facing=north,half=upper,hinge=left]`);
  setBlock(5, platY + 3, 3, woodPlanks);

  // Clear interior (3x3x3 volume)
  for (let x = 4; x <= 6; x++) {
    for (let z = 4; z <= 6; z++) {
      for (let y = platY + 1; y <= platY + 3; y++) {
        setBlock(x, y, z, "minecraft:air");
      }
    }
  }

  // Ceiling
  for (let x = 3; x <= 7; x++) {
    for (let z = 3; z <= 7; z++) {
      if ((x - 5) * (x - 5) + (z - 5) * (z - 5) <= 8) {
        setBlock(x, platY + 4, z, woodPlanks);
      }
    }
  }

  // ==========================================
  // 4. SHELF FUNGI BRACKETS (Extending from walls)
  // ==========================================
  const shelfSide = Math.floor(rng() * 3);
  if (shelfSide === 0) {
    // East shelf bracket
    setBlock(8, platY + 1, 5, "minecraft:brown_mushroom_block");
    setBlock(8, platY + 1, 4, "minecraft:brown_mushroom_block");
    setBlock(8, platY + 1, 6, "minecraft:brown_mushroom_block");
    setBlock(8, platY, 5, woodStairs + "[facing=east,half=top]");
  } else if (shelfSide === 1) {
    // West shelf bracket
    setBlock(2, platY + 1, 5, "minecraft:brown_mushroom_block");
    setBlock(2, platY + 1, 4, "minecraft:brown_mushroom_block");
    setBlock(2, platY + 1, 6, "minecraft:brown_mushroom_block");
    setBlock(2, platY, 5, woodStairs + "[facing=west,half=top]");
  } else {
    // Low bracket near stilt base
    setBlock(2, platY - 1, 3, "minecraft:brown_mushroom_block");
    setBlock(1, platY - 1, 3, woodSlab);
  }

  // ==========================================
  // 5. THATHOED MUSHROOM DOME & EAVES
  // ==========================================
  const capTiers = [
    { dy: 3, rMinSq: 13.0, rMaxSq: 23.5, solid: false }, // Drooping eaves skirt
    { dy: 4, rMinSq: 9.0,  rMaxSq: 22.0, solid: false }, // Lower brim
    { dy: 5, rMinSq: 0,    rMaxSq: 16.0, solid: true },  // Mid dome
    { dy: 6, rMinSq: 0,    rMaxSq: 8.5,  solid: true },  // Upper dome
    { dy: 7, rMinSq: 0,    rMaxSq: 3.5,  solid: true },  // Crown
    { dy: 8, rMinSq: 0,    rMaxSq: 1.0,  solid: true }   // Spire peak
  ];

  for (const tier of capTiers) {
    const y = platY + tier.dy;
    if (y >= 15) continue;

    for (let x = 0; x <= 10; x++) {
      for (let z = 0; z <= 10; z++) {
        const dx = x - 5;
        const dz = z - 5;
        const d2 = dx * dx + dz * dz;

        if (d2 <= tier.rMaxSq && (tier.solid || d2 >= tier.rMinSq)) {
          // Spot patterning
          const isSpot = (d2 >= tier.rMaxSq - 4.5) && (((x * 7 + y * 13 + z * 19) % 5 === 0));
          let blk = isSpot ? spotBlock : primaryCap;

          // Eaves trim variation for brown bonnet
          if (capType === 1 && tier.dy === 3) {
            blk = (d2 >= 19.0) ? woodSlab : "minecraft:brown_mushroom_block";
          }

          setBlock(x, y, z, blk);
        }
      }
    }
  }

  // Spore chimney or glowing finial atop the cap
  const crownY = Math.min(14, platY + 8);
  if (capType === 2) {
    setBlock(5, crownY, 5, "minecraft:shroomlight");
    if (crownY + 1 < 15) setBlock(5, crownY + 1, 5, woodFence);
  } else if (capType === 0) {
    setBlock(5, crownY, 5, "minecraft:ochre_froglight");
    if (crownY + 1 < 15) setBlock(5, crownY + 1, 5, woodTrapdoor);
  } else {
    setBlock(5, crownY, 5, stemBlock);
    if (crownY + 1 < 15) setBlock(5, crownY + 1, 5, woodFence);
  }

  // ==========================================
  // 6. DANGLING SPORE LANTERNS
  // ==========================================
  const lanternCorners = [
    [2, 2], [8, 2], [2, 8], [8, 8],
    [5, 1], [1, 5], [9, 5], [5, 9]
  ];

  for (const [lx, lz] of lanternCorners) {
    if (rng() < 0.6) {
      const eaveY = platY + 3;
      // Ensure strictly supported from roof geometry above
      setBlock(lx, eaveY, lz, primaryCap);
      setBlock(lx, eaveY - 1, lz, "minecraft:chain");

      const lightBlock = (rng() < 0.5) ? "minecraft:lantern[hanging=true]" : "minecraft:shroomlight";
      setBlock(lx, eaveY - 2, lz, lightBlock);
    }
  }

  return {
    name: "cap_stilt_dwelling",
    seatY: 0,
    anchors: {
      front: [5, platY + 1, 0],
      door: [5, platY + 1, 2]
    },
    interiors: [
      {
        min: [4, platY + 1, 4],
        max: [6, platY + 3, 6],
        kind: "quarters"
      }
    ]
  };
}

